param([Parameter(Mandatory)][string]$Root,[Parameter(Mandatory)][string]$TagVersion,[string]$PreviousVersion)
$ErrorActionPreference='Stop';$v=(Get-Content "$Root\VERSION" -Raw).Trim();$p=(Get-Content "$Root\package.json" -Raw|ConvertFrom-Json).version;$t=(Get-Content "$Root\src-tauri\tauri.conf.json" -Raw|ConvertFrom-Json).version;$raw=Get-Content "$Root\Cargo.toml" -Raw;$section=[regex]::Match($raw,'(?s)\[workspace\.package\](.*?)(?=\r?\n\[|$)').Groups[1].Value;$c=[regex]::Match($section,'(?m)^version\s*=\s*"([^"]+)"').Groups[1].Value;if(@($v,$p,$t,$c)|?{$_ -ne $TagVersion}){throw 'version contract mismatch'};if($PreviousVersion -and [version]$TagVersion -le [version]$PreviousVersion){throw 'tag must exceed previous'};Write-Output 'version-contract: pass'
